import { Injectable, inject } from '@angular/core';
import { TostbarService } from '../../core/services/tost/tostbar.service';
import { HttpErrorResponse } from '@angular/common/http';

@Injectable({
  providedIn: 'root'
})
export class RtErrorAdapter {
  private tost = inject(TostbarService);

  handle(error: any, context?: string) {
    console.error(`RT Error [${context || 'Unknown'}]:`, error);
    
    let message = 'An unexpected error occurred.';
    
    if (error instanceof HttpErrorResponse) {
        message = error.error?.message || error.message || message;
    } else if (typeof error === 'string') {
        message = error;
    } else if (error?.message) {
        message = error.message;
    }

    this.tost.error(message);
  }
}
