import { Injectable, computed, inject, signal } from '@angular/core';
import { CommunicationService } from '../../shared/services/communication/communication.service';
import { SecureStorageService } from '../../core/services/storage/secure-storage.service';
import { HeaderService } from '../../core/services/header/header.service';
import { UserDetail, DocumentTab } from '@rt/models';
import { sessionDetail } from '../interfaces';
import { MatDialog } from '@angular/material/dialog';
import { RealtimesettingComponent } from '../components/realtimesetting/realtimesetting.component';
import { AssignserversComponent } from '../components/assignservers/assignservers.component';
import { CaseDetailResponce } from '../../adminpanel/interfaces/casebuilder.interface';
import { IndividualService } from '../../userpanel/services/individual/individual.service';
import { CasedetailService } from '../../shared/services/casedetail/casedetail.service';

import { RealtimeService } from '../services';
import { CommonfunctionService, MULTI_DEVICE_EXEMPT_CASE_ID, MULTI_DEVICE_SESSION_KEY } from '../../core/utility/commonfunction.service';
import { TranslateService } from '@ngx-translate/core';
import { RtErrorAdapter } from '../adapters/rt-error.adapter';

@Injectable({
  providedIn: 'root'
})
export class RealtimeFacade {
  private ss = inject(SecureStorageService);
  private cs = inject(CommunicationService);
  private hs = inject(HeaderService);
  private dialog = inject(MatDialog);
  private realtimeService = inject(RealtimeService);
  private individualService = inject(IndividualService);
  private cf = inject(CommonfunctionService);
  private translate = inject(TranslateService);
  private errorAdapter = inject(RtErrorAdapter);
  private casedetailService = inject(CasedetailService);

  // State Signals
  private _user = signal<UserDetail | null>(null);
  private _isDemoStarted = signal<boolean>(false);
  public currentCase = signal<CaseDetailResponce | null>(null);

  // Readonly Signals
  user = this._user.asReadonly();
  isDemoStarted = this._isDemoStarted.asReadonly();
  
  activeSession = signal<string | null>(null);
  sessionDetail = signal<sessionDetail | null>(null);

  // UI State Signals
  private _uiState = signal({
    isSplitScreen: false,
    splitSessionId: null as string | null, // Added splitSessionId
    isCompareMode: false, // Document Compare (PDF)
    isFeedCompare: false, // Transcript Compare (Feed vs Feed)
    sideNavPanelLeft: 420,
    feedPanelLeft: 420,
    zoomLevel: 1
  });
  uiState = this._uiState.asReadonly();

  // Doc viewer split ratio (percent of viewport occupied by the floating PDF
  // panel on the right). Default is 50 (i.e. 50/50 split). Clamped to
  // [MIN, MAX] so neither pane vanishes.
  //
  // Persistence is intentionally per-session only — every fresh page load
  // resets to the 50/50 default. We tried localStorage persistence earlier
  // but it caused stale values to surface unexpectedly (e.g. on a different
  // monitor / resolution), making the "default 50/50 at all sizes" promise
  // feel broken. Drag still updates the signal in-memory for the lifetime
  // of the tab; closing/reloading returns to 50/50.
  private static readonly DOC_RATIO_MIN = 20;
  private static readonly DOC_RATIO_MAX = 80;
  private static readonly DOC_RATIO_DEFAULT = 50;

  private _docViewerRatio = signal<number>(RealtimeFacade.DOC_RATIO_DEFAULT);
  docViewerRatio = this._docViewerRatio.asReadonly();

  // `persist` is kept as a no-op for call-site compatibility — the drag
  // handler still passes it. Width is in-memory only, by design.
  setDocViewerRatio(ratio: number, _persist: boolean = true) {
    const clamped = Math.min(
      RealtimeFacade.DOC_RATIO_MAX,
      Math.max(RealtimeFacade.DOC_RATIO_MIN, ratio)
    );
    this._docViewerRatio.set(clamped);
  }

  persistDocViewerRatio() {
    // No-op: see docViewerRatio comment. Method kept so the drag-end
    // handler in the shell component doesn't need to change.
  }

  resetDocViewerRatio() {
    this.setDocViewerRatio(RealtimeFacade.DOC_RATIO_DEFAULT);
  }

  // UI State Actions
  setSplitScreen(enabled: boolean, sessionId: string | null = null) {
    this._uiState.update(s => ({ ...s, isSplitScreen: enabled, splitSessionId: sessionId }));
  }

  setCompareMode(enabled: boolean) {
    this._uiState.update(s => ({ ...s, isCompareMode: enabled }));
  }


  setFeedCompare(enabled: boolean) {
    this._uiState.update(s => ({ ...s, isFeedCompare: enabled }));
  }

  setZoomLevel(level: number) {
    this._uiState.update(s => ({ ...s, zoomLevel: level }));
  }

  setPanelWidths(sideNav: number, feed: number) {
    this._uiState.update(s => ({ ...s, sideNavPanelLeft: sideNav, feedPanelLeft: feed }));
  }

  constructor() {
    this.loadUser();
  }

  private async loadUser() {
    const user = await this.ss.getUserInfo();
    this._user.set(user);
  }

  // Realtime Session Management
  async initializeSession(nCaseid: string, nSesid: string | null = null): Promise<string | null> {
      // Set multi-device flag for exempt case
      if (nCaseid === MULTI_DEVICE_EXEMPT_CASE_ID) {
        localStorage.setItem(MULTI_DEVICE_SESSION_KEY, 'true');
      }

      // 1. Fetch Case Detail
      if(nCaseid) {
          try {
              const res = await this.casedetailService.getCaseInfo(nCaseid);
              if(res) {
                 const caseDetail = Array.isArray(res) ? res[0] : res;
                 this.currentCase.set(caseDetail);
                 this.hs.Casedetail = caseDetail;
              }
          } catch(e) {
              console.error('Failed to load case detail', e);
          }
      }

      let session = nSesid;
      if (!session) {
          session = await this.realtimeService.getActiveSession(nCaseid);
      }
      this.activeSession.set(session);
      
      // Fetch details if we have session and user
      const user = this._user();
      if(session && user) {
          try {
             // Assuming getSessionDetail exists on service
             const detail = await this.realtimeService.getSessionDetail(session, user.nUserid); 
             this.sessionDetail.set(detail);
          } catch(e) {
              console.error('Failed to load session detail', e);
          }
      }
      return session;
  }


  toggleDemo() {
    const currentState = this._isDemoStarted();
    if (currentState) {
      this.cs.callFunction({ event: 'STOP-DEMO', flag: true });
    } else {
      this.cs.callFunction({ event: 'START-DEMO', flag: true });
    }
    this._isDemoStarted.set(!currentState);
  }

  resetDemoState() {
    this._isDemoStarted.set(false);
  }

  resetState(): void {
    localStorage.removeItem(MULTI_DEVICE_SESSION_KEY);
    this._user.set(null);
    this._isDemoStarted.set(false);
    this.currentCase.set(null);
    this.activeSession.set(null);
    this.sessionDetail.set(null);
    this._uiState.set({
      isSplitScreen: false,
      splitSessionId: null,
      isCompareMode: false,
      isFeedCompare: false,
      sideNavPanelLeft: 420,
      feedPanelLeft: 420,
      zoomLevel: 1
    });
    this._compareState.set({
      sessionL: null,
      sessionR: null,
      documentList: [],
      demoDocList: [],
      currentIndex: 0
    });
  }

  goUserHome() {
    this.hs.goUserHome();
  }

  exitRealtime() {
    window.close();
  }

  isOnRealtimeDashboard(): boolean {
    return location.href.includes('realtime/dashboard');
  }

  // Comparison State
  private _compareState = signal({
    sessionL: null as string | null,
    sessionR: null as string | null,
    documentList: [] as DocumentTab[],
    demoDocList: [] as DocumentTab[],
    currentIndex: 0
  });
  compareState = this._compareState.asReadonly();

  // Comparison Actions
  setCompareSessions(left: string | null, right: string | null) {
      this._compareState.update(s => ({ ...s, sessionL: left, sessionR: right }));
      // For Feed Compare, we usually expect left and right to be set.
  }

  updateCompareDocumentList(list: DocumentTab[]) {
      this._compareState.update(s => ({ ...s, documentList: list }));
  }

  updateDemoDocList(list: DocumentTab[]) {
      this._compareState.update(s => ({ ...s, demoDocList: list }));
  }

  setCompareIndex(index: number) {
      this._compareState.update(s => ({ ...s, currentIndex: index }));
  }

  // Complex Logic moved from Component
  enableFeedCompare(nLid: string, nRid: string) {
    this.setSplitScreen(false, null); // disable switch mode
    this.setCompareMode(false); // Ensure Doc compare is off
    this.setFeedCompare(true);
    this.setCompareSessions(nLid, nRid);
  }

  disableFeedCompare() {
    this.setFeedCompare(false);
    this.setCompareSessions(null, null);
  }

  enableSwitchMode(nSesid: string | null) {
    const sessionToUse = nSesid || this.activeSession();
    this.disableFeedCompare();
    this.setCompareMode(false);
    this.setSplitScreen(true, sessionToUse);
  }

  disableSwitchMode() {
    this.setSplitScreen(false, null);
  }


  // Internal Helper
  private senitizeUrl(data: any, pageNo?: number, index?: number): any {
    const nCaseid = this.currentCase()?.nCaseid || '';
    const isCompare = this.uiState().isCompareMode;
    return this.cf.senitizeUrl(
      data.originalPath, 
      data.nBundledetailid, 
      nCaseid, 
      true, 
      null, 
      pageNo, 
      null, 
      isCompare, 
      index, 
      null, null, 
      data.nRFSid || null, 
      data.nRDocid || null, 
      data.nRWebid || null, 
      null, null, null, null, null, null, 1
    );
  }

  async handleOpenCompareMode(data: { nDocid: string, nBundledetailid: string }) {
    try {
      this.setCompareIndex(1);
      this.setCompareMode(true);
      // Ensure Feed Compare is OFF
      this.setFeedCompare(false);
      this.setSplitScreen(false);

      this.updateCompareDocumentList([]);
      this.updateDemoDocList([]);

      // Create first document (realtime feed)
      // Note: activeSession might be null if not initialized, but ideally it is.
      const firstDoc: DocumentTab = {
        nBundledetailid: '',
        cFilename: this.translate.instant('rt.realtime.realtimeFeed'),
        originalPath: '',
        cPath: null,
        isLoaded: true,
        isChecked: true,
        isActivate: true,
        nSesid: this.activeSession(),
        nRFSid: null,
        nRDocid: null,
        nRWebid: null,
        currentPage: 1,
        onPage: 1
      };
      
      this.updateCompareDocumentList([firstDoc]);

      await this.fetchAllDocsForCompare(data.nDocid, data.nBundledetailid);

    } catch (error) {
      this.errorAdapter.handle(error, 'Open Compare Mode');
    }
  }

  startCompareWithDocuments(documentsData: any[]) {
    if (!documentsData?.length) return;

    // this.compareMode = true;
    this.setCompareMode(true);
    // this.compareEnabled = false;
    this.setFeedCompare(false);
    this.setSplitScreen(false);
    this.setCompareIndex(1);

    const docList = documentsData.map((doc, index) => {
      const onPage = doc.jLinktype?.pages?.[0] || doc.jLinktype?.start || 1;
      const element = {
        nBundledetailid: doc.nBundledetailid,
        cFilename: doc.cFilename,
        originalPath: doc.cPath,
        cPath: index === 0 ? null : this.senitizeUrl({ originalPath: doc.cPath, nBundledetailid: doc.nBundledetailid }, onPage, index + 1),
        isLoaded: true,
        isChecked: true,
        isActivate: index === 0,
        onPage: onPage,
        currentPage: onPage,
        nSesid: index === 0 ? this.activeSession() : null,
        nRDocid: doc.nDocid
      } as DocumentTab;
      return element;
    });

    this.updateCompareDocumentList(docList);
  }
  async fetchAllDocsForCompare(docId: string, nBundledetailid: string) {
    try {
      const ids = [docId];
      const docs: any = await this.individualService.fetchAllDocs(ids);
      const currentList = [...this.compareState().documentList];

      if (docs.length > 0) {
        if (docs.length > 2) {
          // Find the selected document
          const selectedDoc = docs[1].find((a: any) => a.nBundledetailid == nBundledetailid);

          if (selectedDoc) {
            // Set page information
            if (selectedDoc?.jLinktype && selectedDoc?.jLinktype?.pages?.length) {
              selectedDoc.onPage = selectedDoc?.jLinktype?.pages[0];
            } else if (selectedDoc?.jLinktype && selectedDoc?.jLinktype?.start) {
              selectedDoc.onPage = parseInt(selectedDoc?.jLinktype?.start);
            }

            selectedDoc.originalPath = selectedDoc.cPath;
            const element: DocumentTab = {
              nBundledetailid: selectedDoc.nBundledetailid,
              cFilename: selectedDoc.cFilename,
              originalPath: selectedDoc.cPath,
              cPath: this.senitizeUrl(selectedDoc, selectedDoc.onPage, 2),
              isLoaded: true,
              isChecked: true,
              isActivate: true,
              currentPage: selectedDoc.onPage || 1,
              onPage: selectedDoc.onPage,
              nRFSid: selectedDoc.nRFSid || null,
              nRDocid: selectedDoc.nRDocid || null,
              nRWebid: selectedDoc.nRWebid || null,
              nSesid: null
            };
            currentList.push(element);
          }

          // Populate demo doc list
          const demoList: DocumentTab[] = [];
          docs[1].map((info: any) => {
            info.originalPath = info.cPath;
            if (info?.jLinktype && info?.jLinktype?.pages?.length) {
              info.onPage = info?.jLinktype?.pages[0];
            } else if (info?.jLinktype && info?.jLinktype?.start) {
              info.onPage = parseInt(info?.jLinktype?.start);
            }

            const element: DocumentTab = {
              nBundledetailid: info.nBundledetailid,
              cFilename: info.cFilename,
              originalPath: info.cPath,
              cPath: this.senitizeUrl(info, info.onPage || 1, 2),
              isLoaded: true,
              isChecked: selectedDoc && selectedDoc.nBundledetailid == info.nBundledetailid,
              isActivate: true,
              currentPage: info.onPage || 1,
              onPage: 1,
              nRFSid: info.nRFSid || null,
              nRDocid: info.nRDocid || null,
              nRWebid: info.nRWebid || null,
              nSesid: null
            };
            demoList.push(element);
          });
          this.updateDemoDocList(demoList);

        } else if (docs.length == 1) {
          // Single document case
          const firstDocData = docs[0];
          const element: DocumentTab = {
            nBundledetailid: firstDocData.nBundledetailid,
            cFilename: firstDocData.cFilename,
            originalPath: firstDocData.cPath,
            cPath: this.senitizeUrl(firstDocData, firstDocData.currentPage || 1, 2),
            isLoaded: true,
            isChecked: true,
            isActivate: true,
            currentPage: firstDocData.currentPage || 1,
            onPage: firstDocData.onPage || 1,
            nRFSid: firstDocData.nRFSid || null,
            nRDocid: firstDocData.nRDocid || null,
            nRWebid: firstDocData.nRWebid || null,
            nSesid: null
          };
          currentList.push(element);
        }
      }
      this.updateCompareDocumentList(currentList);
    } catch (err) {
      console.error('Error fetching documents for compare:', err);
    }
  }
  disableCompareMode() {
    this.setCompareMode(false);
    this.updateCompareDocumentList([]);
    this.setCompareIndex(0);
  }

  handleDocumentSelectionChange(item: DocumentTab, checked: boolean) {
    const currentList = [...this.compareState().documentList];
    if (checked) {
      if (currentList.length < 4) {
        const existingIndex = currentList.findIndex(doc => doc.nBundledetailid === item.nBundledetailid);
        if (existingIndex === -1) {
          const newDoc: DocumentTab = {
            ...item,
            isChecked: true,
            cPath: this.senitizeUrl(item, item.onPage || 1, currentList.length + 1)
          };
          currentList.push(newDoc);
          this.updateCompareDocumentList(currentList);
        }
      }
    } else {
      const index = currentList.findIndex(doc => doc.nBundledetailid === item.nBundledetailid);
      if (index > -1) {
        currentList.splice(index, 1);
        this.updateCompareDocumentList(currentList);
      }
    }
  }

  // Dialogs logic can also be here or in the Container. 
  // For a Facade, it's often cleaner to keep UI concerns (Dialogs) in the Container or a UI Service.
  // I will keep them here for now to strictly decouple the Component from MatDialog if desired, 
  // but typically Dialogs are "UI" so Component invoking them is fine if logic is minimal.
  // However, the prompt asked to move "WebSocket / real-time event logic" to Facade.
}
